rss.channel:
  {{ site.name }}
  {{ B }}/{{ lang }}/
  {{ site['tagline_' ~ lang] }}
  {{ lang }}

{% for d in digests %}


    {{ site.name }} — {{ human_date(d.date, lang) }}
    {{ B }}/{{ lang }}/{{ d.date }}/
    {{ B }}/{{ lang }}/{{ d.date }}/
    {{ rfc822(d.generated) }}
    <ul>{% for g in d.glance[lang] %}<li>{{ g }}</li>{% endfor %}</ul>{% for sec in d.sections %}<h3>{{ sec.title[lang] }}</h3>{% for s in sec.stories %}<p><strong>{{ s.title[lang] }}</strong> {{ s.summary[lang] }} <a href="{{ s.sources[0].url }}">{{ s.sources[0].name }}</a></p>{% endfor %}{% endfor %}

{% endfor %}
